-- Update the article actually linked by the court profile menu item.
SET @profile_article_id := (
  SELECT CAST(SUBSTRING_INDEX(link, 'id=', -1) AS UNSIGNED)
  FROM #__menu
  WHERE menutype='mainmenu' AND path='profil-pengadilan' AND published=1
  ORDER BY id LIMIT 1
);
UPDATE #__content
SET introtext=CONVERT( USING utf8mb4), modified=UTC_TIMESTAMP()
WHERE id=@profile_article_id;
